script:
(function () {
  'use strict';

  function $(id) { return document.getElementById(id); }

  var canvas = $('spectrumCanvas');
  var canvasCtx = canvas.getContext('2d');
  var deviceSelect = $('deviceSelect');
  var btnStart = $('btnStartMic');
  var btnStop = $('btnStopMic');
  var btnMeasureFloor = $('btnMeasureFloor');
  var diagnosticPanel = $('diagnosticPanel');
  var statDominant = $('statDominant');
  var statNoiseFloor = $('statNoiseFloor');
  var statHum = $('statHum');
  var statSampleRate = $('statSampleRate');
  var statDominantLevel = $('statDominantLevel');
  var statNote = $('statNote');
  var statPeak = $('statPeak');
  var statRms = $('statRms');
  var scaleLabels = $('scaleLabels');
  var selectFftSize = $('selectFftSize');
  var selectWeighting = $('selectWeighting');
  var selectView = $('selectView');
  var selectOctave = $('selectOctave');
  var info = {
    crest: $('infoCrest'), headroom: $('infoHeadroom'), clipping: $('infoClipping'), l10: $('infoL10'), l90: $('infoL90'),
    aboveBg: $('infoAboveBg'), variability: $('infoVariability'), range: $('infoRange'), band: $('infoBand'), octave: $('infoOctave'),
    weighted: $('infoWeighted'), resolution: $('infoResolution'), bins: $('infoBins'), window: $('infoWindow')
  };

  var currentStream = null;
  var audioCtx = null;
  var analyser = null;
  var freqData = null;
  var timeData = null;
  var peakHold = null;
  var rafId = null;
  var starting = false;
  var measuringFloor = false;
  var minFreq = 20, maxFreq = 20000;
  var DB_MIN = -110, DB_MAX = -10; // display range of the float spectrum
  var levelLog = [];       // RMS dBFS sampled every 100 ms for L10/L90
  var lastLogTime = 0;
  var clipCount = 0;
  var lastClip = 0;
  var lastReadout = 0;

  var NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
  var BANDS = [
    [20, 60, 'Sub bass'], [60, 250, 'Bass'], [250, 500, 'Low mid'], [500, 2000, 'Mid'],
    [2000, 4000, 'Upper mid'], [4000, 6000, 'Presence'], [6000, 12000, 'Brilliance'], [12000, 24000, 'Air']
  ];

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function resizeCanvas() {
    var rect = canvas.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
  }

  function fmtHz(hz) { return hz >= 1000 ? (hz / 1000).toFixed(2) + ' kHz' : Math.round(hz) + ' Hz'; }
  function fmtDb(db) { return isFinite(db) && db > -200 ? db.toFixed(1) + ' dBFS' : '—'; }

  // IEC 61672 A and C weighting curves (closed form), in dB at frequency f.
  function weightingDb(f) {
    var w = selectWeighting.value;
    if (w === 'Z' || f <= 0) return 0;
    var f2 = f * f, c1 = 20.598997 * 20.598997, c4 = 12194.217 * 12194.217;
    if (w === 'C') {
      var rc = c4 * f2 / ((f2 + c1) * (f2 + c4));
      return 20 * Math.log10(rc) + 0.062;
    }
    var ra = c4 * f2 * f2 / ((f2 + c1) * Math.sqrt((f2 + 107.65265 * 107.65265) * (f2 + 737.86223 * 737.86223)) * (f2 + c4));
    return 20 * Math.log10(ra) + 2.0;
  }

  function binHz(bin) { return bin * audioCtx.sampleRate / analyser.fftSize; }

  // Maps a pixel column to a frequency bin on a LOGARITHMIC axis -- a
  // linear axis compresses everything below 1 kHz (where most speech and
  // instrument fundamentals live) into an unreadable sliver, per this
  // tool's own spec note.
  function binForColumn(x, w, sampleRate) {
    var frac = x / w;
    var freq = minFreq * Math.pow(maxFreq / minFreq, frac);
    var bin = Math.round((freq / (sampleRate / 2)) * analyser.frequencyBinCount);
    return Math.max(0, Math.min(analyser.frequencyBinCount - 1, bin));
  }

  function toFrac(db) { return Math.max(0, Math.min(1, (db - DB_MIN) / (DB_MAX - DB_MIN))); }

  function drawSpectrum(w, h, sampleRate) {
    var barCount = Math.max(1, Math.round(w / 3));
    var barWidth = w / barCount;
    if (!peakHold || peakHold.length !== barCount) peakHold = new Array(barCount).fill(0);
    for (var b = 0; b < barCount; b++) {
      var x = b * barWidth;
      var bin = binForColumn(x, w, sampleRate);
      var value = toFrac(freqData[bin] + weightingDb(binHz(bin)));
      var barH = value * h;
      canvasCtx.fillStyle = '#7c5cff';
      canvasCtx.fillRect(x, h - barH, Math.max(1, barWidth - 1), barH);
      if (value > peakHold[b]) peakHold[b] = value;
      else peakHold[b] = Math.max(0, peakHold[b] - 0.004);
      canvasCtx.fillStyle = 'rgba(124,92,255,.55)';
      canvasCtx.fillRect(x, h - peakHold[b] * h, Math.max(1, barWidth - 1), 2);
    }
  }

  function octaveCenters() {
    var per = parseInt(selectOctave.value, 10) || 3, list = [];
    var nMin = per === 1 ? -5 : -16, nMax = per === 1 ? 4 : 13;
    for (var n = nMin; n <= nMax; n++) list.push(1000 * Math.pow(2, n / per));
    return { per: per, centers: list };
  }

  function nominal(fc) {
    if (fc >= 1000) return (Math.round(fc / 100) / 10) + 'k';
    return String(Math.round(fc));
  }

  // Sum the power of every FFT bin inside each band, then weight at the
  // band centre.
  function octaveLevels() {
    var o = octaveCenters(), out = [];
    var nyq = audioCtx.sampleRate / 2, n = freqData.length;
    o.centers.forEach(function (fc) {
      var lo = fc * Math.pow(2, -1 / (2 * o.per)), hi = fc * Math.pow(2, 1 / (2 * o.per));
      if (lo >= nyq) return;
      var i0 = Math.max(1, Math.floor(lo / nyq * n)), i1 = Math.min(n - 1, Math.max(i0, Math.floor(hi / nyq * n)));
      var p = 0;
      for (var i = i0; i <= i1; i++) p += Math.pow(10, freqData[i] / 10);
      out.push({ fc: fc, db: 10 * Math.log10(p + 1e-30) + weightingDb(fc) });
    });
    return out;
  }

  function drawOctave(w, h) {
    var bands = octaveLevels();
    var bw = w / bands.length;
    var dpr = window.devicePixelRatio || 1;
    canvasCtx.font = (9 * dpr) + 'px sans-serif';
    bands.forEach(function (b, i) {
      var v = toFrac(b.db) * h;
      canvasCtx.fillStyle = '#7c5cff';
      canvasCtx.fillRect(i * bw + 1, h - v, Math.max(1, bw - 2), v);
      if (bands.length <= 10 || i % 3 === 1) {
        canvasCtx.fillStyle = '#6b6b80';
        canvasCtx.fillText(nominal(b.fc), i * bw + 2, 10 * dpr);
      }
    });
  }

  function percentile(arr, p) {
    if (!arr.length) return NaN;
    var s = arr.slice().sort(function (a, b) { return a - b; });
    return s[Math.min(s.length - 1, Math.max(0, Math.round((s.length - 1) * p)))];
  }

  function noteFor(f) {
    var n = 12 * Math.log2(f / 440) + 69, r = Math.round(n), cents = Math.round((n - r) * 100);
    return NOTE_NAMES[((r % 12) + 12) % 12] + (Math.floor(r / 12) - 1) + (cents ? ' ' + (cents > 0 ? '+' : '') + cents + '¢' : '');
  }

  function bandFor(f) {
    for (var i = 0; i < BANDS.length; i++) if (f >= BANDS[i][0] && f < BANDS[i][1]) return BANDS[i][2] + ' (' + fmtHz(BANDS[i][0]) + '–' + fmtHz(BANDS[i][1]) + ')';
    return '—';
  }

  function octaveBandFor(f) {
    var o = octaveCenters(), best = o.centers[0];
    o.centers.forEach(function (fc) { if (Math.abs(Math.log2(f / fc)) < Math.abs(Math.log2(f / best))) best = fc; });
    return nominal(best) + ' Hz ' + (o.per === 1 ? '1/1' : '1/3') + '-octave band';
  }

  function drawFrame() {
    rafId = requestAnimationFrame(drawFrame);
    if (!analyser) return;
    analyser.getFloatFrequencyData(freqData);

    var w = canvas.width, h = canvas.height;
    canvasCtx.clearRect(0, 0, w, h);
    var sampleRate = audioCtx.sampleRate;
    if (selectView.value === 'octave') drawOctave(w, h); else drawSpectrum(w, h, sampleRate);

    // Time-domain peak / RMS for headroom, crest factor and clipping.
    var now = performance.now();
    var sumSq = 0, pk = 0, i;
    if (analyser.getFloatTimeDomainData) analyser.getFloatTimeDomainData(timeData);
    for (i = 0; i < timeData.length; i++) { var a = Math.abs(timeData[i]); if (a > pk) pk = a; sumSq += timeData[i] * timeData[i]; }
    var rmsDb = 10 * Math.log10(sumSq / timeData.length + 1e-12);
    var peakDb = pk > 0 ? 20 * Math.log10(pk) : -120;
    if (pk >= 0.99 && now - lastClip > 500) { clipCount++; lastClip = now; }
    if (now - lastLogTime >= 100) {
      lastLogTime = now;
      levelLog.push(rmsDb);
      if (levelLog.length > 6000) levelLog.shift(); // last 10 minutes
    }

    if (now - lastReadout < 150) return; // keep numbers readable
    lastReadout = now;

    var maxVal = -Infinity, maxBin = 0;
    for (i = 2; i < freqData.length; i++) {
      var v = freqData[i] + weightingDb(binHz(i));
      if (v > maxVal) { maxVal = v; maxBin = i; }
    }
    if (maxVal > -90) {
      var dominantHz = binHz(maxBin);
      statDominant.textContent = fmtHz(dominantHz);
      statDominantLevel.textContent = fmtDb(freqData[maxBin]);
      statNote.textContent = noteFor(dominantHz);
      info.range.textContent = dominantHz < 250 ? 'Bass' : dominantHz < 4000 ? 'Mid' : 'Treble';
      info.band.textContent = bandFor(dominantHz);
      info.octave.textContent = octaveBandFor(dominantHz);
      info.weighted.textContent = (freqData[maxBin] + weightingDb(dominantHz)).toFixed(1) + ' dB' + (selectWeighting.value === 'Z' ? 'FS (Z)' : selectWeighting.value);
    }

    statPeak.textContent = fmtDb(peakDb);
    statRms.textContent = fmtDb(rmsDb);
    info.crest.textContent = (peakDb - rmsDb).toFixed(1) + ' dB';
    info.headroom.textContent = (-peakDb).toFixed(1) + ' dB';
    info.clipping.textContent = clipCount ? clipCount + ' clip event' + (clipCount === 1 ? '' : 's') + ' — lower the input' : 'None';
    if (levelLog.length >= 20) {
      var l10 = percentile(levelLog, 0.9), l90 = percentile(levelLog, 0.1);
      info.l10.textContent = fmtDb(l10);
      info.l90.textContent = fmtDb(l90);
      info.aboveBg.textContent = (rmsDb - l90).toFixed(1) + ' dB';
      info.variability.textContent = (l10 - l90).toFixed(1) + ' dB';
    }

    // Mains hum: compare magnitude right at 50/60 Hz against the
    // surrounding noise floor -- a genuine hum spike stands out sharply
    // from nearby bins, unlike broadband noise.
    var hum50 = binMagnitude(50, sampleRate), hum60 = binMagnitude(60, sampleRate);
    var neighborhood = binMagnitude(150, sampleRate) + 6;
    if (hum50 > neighborhood && hum50 >= hum60) {
      statHum.textContent = '50 Hz detected';
    } else if (hum60 > neighborhood) {
      statHum.textContent = '60 Hz detected';
    } else {
      statHum.textContent = 'None detected';
    }
  }

  function binMagnitude(freq, sampleRate) {
    var bin = Math.round((freq / (sampleRate / 2)) * analyser.frequencyBinCount);
    bin = Math.max(0, Math.min(analyser.frequencyBinCount - 1, bin));
    return freqData[bin];
  }

  // Deliberately timer-driven, not requestAnimationFrame -- this is a
  // background measurement, not a rendering task, and rAF is fully
  // suspended whenever the tab isn't visible. A user briefly switching tabs
  // mid-measurement would otherwise leave this permanently stuck.
  function measureNoiseFloor() {
    if (!analyser || measuringFloor) return;
    measuringFloor = true;
    btnMeasureFloor.disabled = true;
    var energies = [];
    var buf = new Float32Array(analyser.fftSize);
    var intervalId = setInterval(function () {
      if (!analyser || !analyser.getFloatTimeDomainData) return;
      analyser.getFloatTimeDomainData(buf);
      var s = 0;
      for (var i = 0; i < buf.length; i++) s += buf[i] * buf[i];
      energies.push(s / buf.length);
    }, 50);
    setTimeout(function () {
      clearInterval(intervalId);
      measuringFloor = false;
      if (!analyser) return;
      var avg = energies.length ? energies.reduce(function (a, b) { return a + b; }, 0) / energies.length : 0;
      statNoiseFloor.textContent = avg > 0 ? Math.round(10 * Math.log10(avg)) + ' dBFS' : '—';
      btnMeasureFloor.disabled = false;
    }, 2000);
  }

  function updateStaticInfo() {
    if (!analyser || !audioCtx) return;
    var sr = audioCtx.sampleRate, n = analyser.fftSize;
    info.resolution.textContent = (sr / n).toFixed(2) + ' Hz per bin';
    info.bins.textContent = String(analyser.frequencyBinCount);
    info.window.textContent = (n / sr * 1000).toFixed(1) + ' ms';
  }

  function updateScaleLabels() {
    if (selectView.value === 'octave') {
      var c = octaveCenters().centers;
      scaleLabels.innerHTML = '<span>' + nominal(c[0]) + ' Hz</span><span>' + nominal(c[c.length - 1]) + ' Hz</span>';
    } else {
      scaleLabels.innerHTML = '<span>20 Hz</span><span>200 Hz</span><span>2 kHz</span><span>20 kHz</span>';
    }
  }

  // Same overall stopStream() shape as microphone-test-online's own script
  // (see this project's CLAUDE.md) -- audio teardown additionally closes
  // the AudioContext.
  function stopStream() {
    if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    if (audioCtx) {
      audioCtx.close().catch(function () {});
      audioCtx = null;
    }
    analyser = null;
    peakHold = null;
    levelLog = [];
    clipCount = 0;
    canvasCtx.clearRect(0, 0, canvas.width, canvas.height);
    btnStop.disabled = true;
    btnMeasureFloor.disabled = true;
    [statDominant, statNoiseFloor, statHum, statSampleRate, statDominantLevel, statNote, statPeak, statRms].forEach(function (el) { el.textContent = '—'; });
    Object.keys(info).forEach(function (k) { info[k].textContent = '—'; });
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Microphone access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No microphone was detected.</strong> Connect a microphone and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your microphone is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This microphone doesn’t support the requested settings.</strong> Try another microphone from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Microphone access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the microphone.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var mics = devices.filter(function (d) { return d.kind === 'audioinput'; });
    deviceSelect.innerHTML = '';
    mics.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Microphone ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = mics.length === 0;
  }

  function startMic(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    resizeCanvas();
    setDiagnostic([{ sev: '', html: 'Requesting microphone access…' }]);
    btnStart.disabled = true;

    // echoCancellation/noiseSuppression/autoGainControl are ON by default
    // and will actively distort the spectrum -- disabling them is the one
    // thing that makes this measurement meaningful, per this tool's own
    // spec note.
    var constraints = {
      audio: {
        deviceId: deviceId ? { exact: deviceId } : undefined,
        echoCancellation: false,
        noiseSuppression: false,
        autoGainControl: false,
      },
    };

    navigator.mediaDevices.getUserMedia(constraints)
      .then(function (stream) {
        currentStream = stream;
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        audioCtx.resume().catch(function () {});
        var source = audioCtx.createMediaStreamSource(stream);
        analyser = audioCtx.createAnalyser();
        analyser.fftSize = parseInt(selectFftSize.value, 10) || 2048;
        analyser.smoothingTimeConstant = 0.7;
        freqData = new Float32Array(analyser.frequencyBinCount);
        timeData = new Float32Array(analyser.fftSize);
        source.connect(analyser);

        var track = stream.getAudioTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        statSampleRate.textContent = Math.round(audioCtx.sampleRate) + ' Hz';
        updateStaticInfo();
        btnStop.disabled = false;
        btnMeasureFloor.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Microphone is live.</strong> Make some noise to see the spectrum respond, or stay silent and measure your noise floor.' }]);
        drawFrame();

        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  btnStart.addEventListener('click', function () { startMic(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Microphone stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startMic(deviceSelect.value); });
  btnMeasureFloor.addEventListener('click', measureNoiseFloor);
  selectFftSize.addEventListener('change', function () {
    if (!analyser) return;
    analyser.fftSize = parseInt(selectFftSize.value, 10) || 2048;
    freqData = new Float32Array(analyser.frequencyBinCount);
    timeData = new Float32Array(analyser.fftSize);
    peakHold = null;
    updateStaticInfo();
  });
  selectWeighting.addEventListener('change', function () { peakHold = null; });
  selectView.addEventListener('change', updateScaleLabels);
  selectOctave.addEventListener('change', updateScaleLabels);

  window.addEventListener('resize', resizeCanvas);
  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  resizeCanvas();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support microphone access.</strong>' }]);
    btnStart.disabled = true;
  }
})();
